"""Persistent shared JSON cache for public demonstration profiles."""
import json
import os
import fcntl
import time
from app.config import DIR, CACHE_PATH, CACHE_TTL

def get_or_load(key, loader):
    if not os.path.exists(CACHE_PATH):
        return loader()
    now = time.time()
    with open(CACHE_PATH, 'r') as f:
        data = json.load(f)
    if key not in data:
        return loader()
    entry = data[key]
    if now - entry['stored_at'] >= 86400:
        return loader()
    return entry['value']

